CREATE TABLE app_user(id uuid PRIMARY KEY, login varchar(120) UNIQUE NOT NULL, password_hash text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Yekaterinburg', version bigint NOT NULL DEFAULT 0);
CREATE TABLE brew_profile(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, name varchar(200) NOT NULL, default_cup_volume_ml integer NOT NULL CHECK(default_cup_volume_ml BETWEEN 10 AND 2000), recipe jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 0, deleted_at timestamptz);
CREATE TABLE personal_lot(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, name varchar(200) NOT NULL, roaster_name varchar(120), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, deleted_at timestamptz, UNIQUE(id,owner_id));
CREATE TABLE coffee_bag(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, lot_id uuid NOT NULL, mass_g numeric NOT NULL CHECK(mass_g BETWEEN 1 AND 5000), status text NOT NULL CHECK(status IN ('ACTIVE','STOCK','FINISHED')), purchased_on date, roasted_on date, opened_at timestamptz, finished_at timestamptz, purchase_price numeric CHECK(purchase_price>=0), currency text NOT NULL DEFAULT 'RUB', note text, final_rating integer CHECK(final_rating BETWEEN 1 AND 5), final_repurchase text, final_comment text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, deleted_at timestamptz, UNIQUE(id,owner_id), FOREIGN KEY(lot_id,owner_id) REFERENCES personal_lot(id,owner_id));
CREATE TABLE bag_status_event(id uuid PRIMARY KEY, bag_id uuid NOT NULL REFERENCES coffee_bag, from_status text, to_status text NOT NULL, changed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasting(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, bag_id uuid NOT NULL, tasted_at timestamptz NOT NULL, overall_rating integer NOT NULL CHECK(overall_rating BETWEEN 1 AND 5), sensory jsonb NOT NULL, repurchase text, comment text, brew_snapshot jsonb NOT NULL, preparation_uncertain boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, deleted_at timestamptz, UNIQUE(id,owner_id), FOREIGN KEY(bag_id,owner_id) REFERENCES coffee_bag(id,owner_id));
CREATE TABLE consumption_event(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, bag_id uuid, consumed_at timestamptz NOT NULL, volume_ml integer NOT NULL CHECK(volume_ml BETWEEN 10 AND 2000), tasting_id uuid UNIQUE, coffee_label varchar(200), comment text, profile_snapshot jsonb NOT NULL, client_event_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version bigint NOT NULL DEFAULT 0, deleted_at timestamptz, UNIQUE(owner_id,client_event_id), FOREIGN KEY(bag_id,owner_id) REFERENCES coffee_bag(id,owner_id), FOREIGN KEY(tasting_id,owner_id) REFERENCES tasting(id,owner_id));
CREATE TABLE idempotency(owner_id uuid NOT NULL REFERENCES app_user, key text NOT NULL, request_hash text NOT NULL, result jsonb NOT NULL, PRIMARY KEY(owner_id,key));
CREATE TABLE media_asset(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES app_user, bag_id uuid, storage_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bag_id,owner_id) REFERENCES coffee_bag(id,owner_id));
CREATE INDEX bag_owner ON coffee_bag(owner_id,updated_at,id);
CREATE INDEX lot_owner ON personal_lot(owner_id,name);
CREATE INDEX tasting_bag ON tasting(owner_id,bag_id,tasted_at,id);
CREATE INDEX consumption_owner_time ON consumption_event(owner_id,consumed_at,id);
